/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    // 1️⃣ Build the query
    Query query = new Query(queryStr(InventOnhand));
    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(InventDim));
    QueryBuildRange qbrWH  = qbds.addRange(fieldNum(InventDim, InventLocationId));
    QueryBuildRange qbrSite  = qbds.addRange(fieldNum(InventDim, InventSiteId));

    qbrWH.value('007');
    qbrSite.value('NORTMDCCC');

    // 2️⃣ Convert the Query to string
    ;

    InventOnhandStorageController controller = InventOnhandStorageController::construct(_args);


    InventOnhandStorageContract contract    = controller ? controller.getDataContractObject() : null;

    if (!contract)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    contract.parmViewInventSiteId(true); // Set to true to view InventSiteId
    contract.parmViewInventLocationId(true); // Set to true to view InventLocationId
    contract.parmQueryString(SysOperationHelper::base64Encode(query.pack()));
    contract.parmExecutionName('InventOnhandReport - TEST from Job'); // Set execution name

    //controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch); // Set execution mode

    controller.parmShowDialog(true);

    controller.parmLoadFromSysLastValue(false);

    //controller.parmInBatch(true);

    //controller.parmDialogCaption('Change Item');

    controller.startOperation();
}
